import { useState } from "react";

const MARKET = [
  { label: "SPX", value: "5,842.31", change: "+0.41%", up: true },
  { label: "NDX", value: "20,614.87", change: "+0.78%", up: true },
  { label: "VIX", value: "14.23", change: "-3.12%", up: false },
  { label: "DXY", value: "103.84", change: "-0.19%", up: false },
  { label: "10Y", value: "4.31%", change: "+0.04", up: true },
  { label: "BTC", value: "87,240", change: "+1.24%", up: true },
];

const SIGNALS = [
  { ticker: "NVDA", signal: "Options volume Z-score: 3.1", type: "FLOW" },
  { ticker: "SPY", signal: "IV inversion detected at 7-day expiry", type: "IV" },
  { ticker: "AAPL", signal: "Analyst revision diverges from price", type: "SENTIMENT" },
];

const SIGNAL_COLORS = {
  FLOW: "#00d4ff",
  IV: "#ffb800",
  SENTIMENT: "#c084fc",
};

const glass = {
  background: "rgba(8, 20, 36, 0.55)",
  backdropFilter: "blur(18px)",
  WebkitBackdropFilter: "blur(18px)",
  border: "1px solid rgba(0, 180, 255, 0.14)",
  borderRadius: 16,
};

export default function Sidebar() {
  const [chatHint, setChatHint] = useState(true);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      {/* Market snapshot */}
      <div style={{ ...glass, padding: 20 }}>
        <div
          style={{
            fontFamily: "'JetBrains Mono', monospace",
            fontSize: 10,
            color: "rgba(0,180,255,0.45)",
            letterSpacing: "0.1em",
            marginBottom: 14,
          }}
        >
          MARKET SNAPSHOT
        </div>
        {MARKET.map((m, i) => (
          <div
            key={m.label}
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              padding: "9px 0",
              borderBottom:
                i < MARKET.length - 1
                  ? "1px solid rgba(0,180,255,0.07)"
                  : "none",
            }}
          >
            <span
              style={{
                fontFamily: "'JetBrains Mono', monospace",
                fontSize: 12,
                color: "rgba(180,210,255,0.45)",
              }}
            >
              {m.label}
            </span>
            <div style={{ textAlign: "right" }}>
              <div
                style={{
                  fontFamily: "'JetBrains Mono', monospace",
                  fontSize: 13,
                  color: "rgba(220,240,255,0.85)",
                }}
              >
                {m.value}
              </div>
              <div
                style={{
                  fontFamily: "'JetBrains Mono', monospace",
                  fontSize: 10,
                  color: m.up ? "#00d282" : "#ff5064",
                }}
              >
                {m.change}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Top signals */}
      <div style={{ ...glass, padding: 20 }}>
        <div
          style={{
            fontFamily: "'JetBrains Mono', monospace",
            fontSize: 10,
            color: "rgba(0,180,255,0.45)",
            letterSpacing: "0.1em",
            marginBottom: 14,
          }}
        >
          TOP SIGNALS TODAY
        </div>
        {SIGNALS.map((s, i) => (
          <div
            key={i}
            className="signal-card"
            style={{
              padding: "10px 12px",
              marginBottom: 6,
              background: "rgba(0,180,255,0.05)",
              borderRadius: 8,
              border: "1px solid rgba(0,180,255,0.1)",
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                marginBottom: 4,
              }}
            >
              <span
                style={{
                  fontFamily: "'JetBrains Mono', monospace",
                  fontSize: 11,
                  color: SIGNAL_COLORS[s.type] || "#00d4ff",
                  fontWeight: 500,
                }}
              >
                {s.ticker}
              </span>
              <span
                style={{
                  fontFamily: "'JetBrains Mono', monospace",
                  fontSize: 9,
                  color: "rgba(0,180,255,0.38)",
                  letterSpacing: "0.08em",
                }}
              >
                {s.type}
              </span>
            </div>
            <span
              style={{
                fontFamily: "'DM Sans', sans-serif",
                fontSize: 12,
                color: "rgba(180,210,255,0.55)",
              }}
            >
              {s.signal}
            </span>
          </div>
        ))}
        <div style={{ marginTop: 8, textAlign: "center" }}>
          <span
            className="cta-link"
            style={{
              fontFamily: "'DM Sans', sans-serif",
              fontSize: 11,
              color: "rgba(0,180,255,0.38)",
              cursor: "pointer",
            }}
          >
            Register to set custom signal alerts →
          </span>
        </div>
      </div>

      {/* AI chatbot hint */}
      {chatHint && (
        <div style={{ ...glass, padding: 18, position: "relative" }}>
          <button
            onClick={() => setChatHint(false)}
            style={{
              position: "absolute",
              top: 10,
              right: 14,
              background: "none",
              border: "none",
              color: "rgba(180,210,255,0.28)",
              cursor: "pointer",
              fontSize: 18,
              lineHeight: 1,
              padding: 0,
            }}
          >
            ×
          </button>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              marginBottom: 10,
            }}
          >
            <div
              style={{
                width: 6,
                height: 6,
                borderRadius: "50%",
                background: "#00d4ff",
                boxShadow: "0 0 6px #00d4ff",
                animation: "pulse 2s infinite",
              }}
            />
            <span
              style={{
                fontFamily: "'JetBrains Mono', monospace",
                fontSize: 10,
                color: "#00d4ff",
                letterSpacing: "0.08em",
              }}
            >
              AI ASSISTANT ACTIVE
            </span>
          </div>
          <p
            style={{
              fontFamily: "'DM Sans', sans-serif",
              fontSize: 12.5,
              color: "rgba(180,210,255,0.55)",
              lineHeight: 1.55,
              marginBottom: 12,
            }}
          >
            Ask about any market, ticker, or concept. No login required on
            the free tier.
          </p>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 5 }}>
            {["What is IV percentile?", "Explain GEX", "Why is VIX falling?"].map(
              (q) => (
                <span
                  key={q}
                  className="tag-pill"
                  style={{
                    background: "rgba(0,180,255,0.07)",
                    border: "1px solid rgba(0,180,255,0.14)",
                    borderRadius: 5,
                    padding: "3px 9px",
                    fontSize: 11,
                    fontFamily: "'DM Sans', sans-serif",
                    color: "rgba(0,180,255,0.65)",
                    cursor: "pointer",
                  }}
                >
                  {q}
                </span>
              )
            )}
          </div>
        </div>
      )}
    </div>
  );
}
